var i=`0133-lobio`;var t=`world-0133`;var a=`GE`;var s=`western-asia`;var o=4;var r=61;var l={en:`Lobio`,ua:`Лобіо`};var d={en:`A classic dish from Georgia, featuring canned kidney beans, bay leaf, yellow onion, garlic. A practical home-kitchen version with measured step ingredients and clear cooking methods.`,ua:`Класична страва з Грузія. Основні складники: консервована червона квасоля, лавровий лист, жовта цибуля, часник. Домашній варіант із поетапними діями та точними кількостями продуктів.`};var g=[{en:`Cook the listed ingredients in simmering water for about 40 minutes until tender; drain well if necessary.`,ua:`Варіть зазначені складники у воді приблизно 40 хвилин до м’якості; за потреби добре злийте воду.`,t:[`boiling`],m:40,i:[[`canned-kidney-beans`,780,`g`],[`water`,260,`ml`],[`bay-leaf`,2,`leaf`]]},{en:`Chop the vegetables as needed. Sauté the listed ingredients over medium heat, stirring, for about 10 minutes until softened and aromatic.`,ua:`Наріжте овочі за потреби. Пасеруйте зазначені складники на середньому вогні, помішуючи, приблизно 10 хвилин до м’якості й аромату.`,t:[`chopping`,`sauteing`],m:10,i:[[`yellow-onion`,210,`g`],[`sunflower-oil`,35,`ml`],[`garlic`,4,`clove`]]},{en:`Stir in these seasonings and additions. Taste, adjust the balance and let the dish stand briefly before serving.`,ua:`Додайте приправи та завершальні складники. Спробуйте, збалансуйте смак і дайте страві трохи настоятися перед подаванням.`,t:[`seasoning`,`finishing-with-herbs`],m:8,i:[[`walnut`,100,`g`],[`ground-coriander`,5,`g`],[`ground-fenugreek`,3,`g`],[`apple-cider-vinegar`,20,`ml`],[`table-salt`,null,`to_taste`],[`ground-black-pepper`,null,`to_taste`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:3,i:[[`cilantro`,30,`g`]]}];var u={slug:i,id:t,country:`GE`,region:s,servings:4,minutes:61,title:l,text:d,steps:g};export{a as country,u as default,t as id,r as minutes,s as region,o as servings,i as slug,g as steps,d as text,l as title};